INSERT INTO email_templates (type, subject, body) VALUES (
  'signup_confirmation',
  'We received your access request — SoCal Autoworks',
  '<!DOCTYPE html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"></head><body style="margin:0;padding:0;background:#f3f4f6;font-family:-apple-system,BlinkMacSystemFont,''Segoe UI'',sans-serif"><table width="100%" cellpadding="0" cellspacing="0" style="background:#f3f4f6;padding:40px 20px"><tr><td><table width="100%" cellpadding="0" cellspacing="0" style="max-width:600px;margin:0 auto"><tr><td style="background:linear-gradient(135deg,#2563eb,#1d4ed8);padding:40px 32px;border-radius:16px 16px 0 0;text-align:center"><h1 style="margin:0;color:#fff;font-size:26px;font-weight:700">SoCal Autoworks</h1><p style="margin:8px 0 0;color:rgba(255,255,255,.85);font-size:15px">Inspection Management System</p></td></tr><tr><td style="background:#fff;padding:36px 32px;border-radius:0 0 16px 16px;box-shadow:0 4px 12px rgba(0,0,0,.08)"><h2 style="margin:0 0 12px;font-size:22px;color:#111827">Hi {{first_name}}, thanks for signing up!</h2><p style="margin:0 0 20px;color:#374151;line-height:1.65;font-size:15px">We received your access request for the SoCal Autoworks Inspection System. A manager or owner will review your request shortly.</p><table width="100%" cellpadding="0" cellspacing="0" style="background:#fefce8;border:1px solid #fde68a;border-radius:10px;padding:20px;margin:0 0 28px"><tr><td><p style="margin:0 0 8px;font-weight:600;color:#92400e;font-size:14px;text-transform:uppercase;letter-spacing:.05em">What happens next?</p><p style="margin:0 0 6px;color:#78350f;font-size:14px">1. A manager reviews your request</p><p style="margin:0 0 6px;color:#78350f;font-size:14px">2. You''ll receive another email once approved</p><p style="margin:0;color:#78350f;font-size:14px">3. Sign in and start your first inspection</p></td></tr></table><p style="margin:0 0 8px;color:#374151;font-size:14px">Your registered email: <strong>{{email}}</strong></p><p style="margin:0;color:#9ca3af;font-size:13px;line-height:1.6">If you did not create this request, you can safely ignore this email.</p></td></tr></table></td></tr></table></body></html>'
) ON CONFLICT (type) DO NOTHING;
